{
    if ($beforeColumnIndex >= 1) {
        return $this->insertNewColumnBefore(Coordinate::stringFromColumnIndex($beforeColumnIndex), $numberOfColumns);
    }

    throw new Exception('Columns can only be inserted before at least column A (1).');
}

