 */
public function removeRow(int $row, int $numberOfRows = 1): static
{
    if ($row < 1) {
        throw new Exception('Rows to be deleted should at least start from row 1.');
    }

    $holdRowDimensions = $this->removeRowDimensions($row, $numberOfRows);
